-- Money transfer: both legs or neither
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 'alice';
UPDATE accounts SET balance = balance + 100 WHERE id = 'bob';
COMMIT; -- crash before this line? Engine rolls back; no money is lost or created

-- On error, abort explicitly:
-- BEGIN; ... ; ROLLBACK;

-- Two concurrent sessions at READ COMMITTED:
-- Session A: BEGIN; SELECT balance FROM accounts WHERE id='alice'; -- 500
-- Session B: BEGIN; UPDATE accounts SET balance=400 WHERE id='alice'; COMMIT;
-- Session A: SELECT balance FROM accounts WHERE id='alice'; -- now 400 (non-repeatable)
-- At REPEATABLE READ, session A would still see 500 in the second SELECT.

-- Critical section at the strongest level:
-- BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
-- UPDATE inventory SET stock = stock - 1 WHERE product_id = 42 AND stock > 0;
-- COMMIT; -- may raise a serialization error under contention: retry the txn

-- Pessimistic: lock the row first, others wait
BEGIN;
SELECT stock FROM inventory WHERE product_id = 42 FOR UPDATE;
-- ... decide, then:
UPDATE inventory SET stock = stock - 1 WHERE product_id = 42;
COMMIT; -- keep it short: locks are held until here

-- Optimistic: check the version at write time
-- UPDATE inventory SET stock = stock - 1, version = version + 1
-- WHERE product_id = 42 AND version = 5;
-- matched 0 rows? Someone else won — re-read and retry.

-- Classic cycle: opposite lock order
-- Txn A: UPDATE accounts SET balance = balance - 10 WHERE id = 1;
--        UPDATE accounts SET balance = balance + 10 WHERE id = 2;
-- Txn B (concurrent): UPDATE accounts SET balance = balance - 10 WHERE id = 2;
--                     UPDATE accounts SET balance = balance + 10 WHERE id = 1;
-- → deadlock: each waits on the other's row. Engine aborts one; retry it.

-- Fix: consistent ordering in both code paths
-- SELECT * FROM accounts WHERE id IN (1, 2) ORDER BY id FOR UPDATE;
